INSERT INTO product_reviews (product_id, reviewer_name, rating, review_text) VALUES
(1, 'Siti Nurhaliza', 5, 'Bagus banget! Jerawat ku berkurang drastis setelah pakai ini rutin. Wajib coba!'),
(1, 'Rina Handayani', 4, 'Lumayan oke, tapi agak bikin kering di awal. Setelah cocok jadi bagus.'),
(1, 'Dea Ananda', 5, 'Harganya terjangkau dan hasilnya memuaskan. Jerawat cepat kempes.'),
(2, 'Putri Maharani', 5, 'Micellar water favorit! Bersih tuntas dan gak bikin perih.'),
(2, 'Lisa Kusuma', 4, 'Oke sih, tapi untuk makeup waterproof butuh usaha lebih.'),
(2, 'Maya Sari', 5, 'Cocok buat kulit sensitif. Wajah jadi lebih cerah juga.'),
(3, 'Ratna Dewi', 5, 'Sunscreen terbaik! Ringan, gak lengket, gak whitecast. Worth it banget!'),
(3, 'Ayu Lestari', 5, 'Ini holy grail sunscreen aku. Pakai tiap hari gak bikin jerawatan.'),
(3, 'Indah Permata', 4, 'Bagus tapi agak pricey. Tapi hasilnya sebanding sih.'),
(4, 'Sinta Wijaya', 5, 'Kulit jadi glowing dan lembab. Favorite serum aku sekarang!'),
(4, 'Nia Rahmawati', 4, 'Bagus tapi butuh waktu untuk lihat hasil cerahnya. Sabar ya!'),
(5, 'Diah Puspita', 5, 'Retinol yang gentle! Cocok untuk pemula. Tekstur kulit membaik.'),
(5, 'Mega Wulandari', 4, 'Hasilnya oke, tapi harus telaten pakai sunscreen pas siang.'),
(5, 'Lina Susanti', 5, 'Fine lines berkurang setelah 2 bulan pakai. Recommended!'),
(6, 'Yuni Kartika', 5, 'Essence yang hydrating banget. Kulit jadi kenyal dan cerah.'),
(6, 'Fitri Anggraini', 4, 'Bagus tapi botolnya cepet habis karena aku pakai banyak hehe.'),
(7, 'Rara Amalia', 5, 'Niacinamide 10% tapi gak bikin iritasi. Flek hitam memudar!'),
(7, 'Tari Purnama', 5, 'Cocok banget untuk kulit kusam. Hasilnya kelihatan cepet.'),
(7, 'Nina Cahaya', 4, 'Bagus tapi agak sticky di awal. Setelah meresap oke sih.'),
(8, 'Bella Pratiwi', 5, 'Gel moisturizer yang perfect! Ringan, cepat meresap, melembabkan.'),
(8, 'Citra Melati', 5, 'Cocok buat kulit berminyak. Gak bikin minyakan tapi tetap lembab.'),
(9, 'Wulan Safitri', 4, 'Lumayan ampuh untuk jerawat yang baru muncul. Cepet kempes.'),
(9, 'Dewi Laksmi', 5, 'Spot treatment terbaik! Jerawat cystic aku jadi lebih kecil.'),
(10, 'Amel Kuswardani', 5, 'Toner exfoliating yang gentle. Kulit jadi halus dan cerah.'),
(10, 'Rini Marlina', 4, 'Bagus tapi jangan keseringan pakai, bisa over-exfoliate.'),
(11, 'Dinda Safira', 5, 'Moisturizer terbaik untuk repair skin barrier. Game changer!'),
(11, 'Vina Ratnasari', 5, 'Kulitku yang sensitif jadi lebih tenang pakai ini. Love it!'),
(12, 'Sari Mulyani', 5, 'Centella toner yang menenangkan banget. Kemerahan hilang!'),
(12, 'Laras Pramesti', 4, 'Bagus untuk kulit sensitif, tapi hasilnya butuh waktu.'),
(13, 'Tika Wahyuni', 4, 'Face wash yang oke untuk kulit berminyak. Tapi agak drying.'),
(13, 'Eka Novita', 5, 'Minyak terkontrol seharian. Harga juga ramah kantong!'),
(14, 'Putri Ayu', 5, 'Sleeping mask yang bikin bangun pagi langsung glowing!'),
(14, 'Nisa Amira', 5, 'Hidrasi maksimal! Kulit jadi kenyal dan lembut banget.'),
(15, 'Yuli Setiawan', 4, 'Clay mask yang bagus untuk deep cleansing. Pori-pori bersih.'),
(15, 'Mira Cahyani', 5, 'Komedo terangkat! Pakai seminggu sekali hasilnya oke.'),
(16, 'Dwi Lestari', 4, 'Scrub yang lembut, gak bikin iritasi. Kulit jadi halus.'),
(16, 'Rina Susilawati', 3, 'Lumayan oke, tapi mungkin butuh yang lebih exfoliating.'),
(17, 'Anisa Putri', 5, 'Vitamin C serum yang gak bikin breakout. Kulit cerah natural!'),
(17, 'Desi Rahmawati', 4, 'Bagus tapi harus disimpan di kulkas biar gak cepet oksidasi.'),
(18, 'Winda Lestari', 5, 'Pelembab ringan yang cocok untuk iklim tropis. Gak gerah!'),
(18, 'Lia Permatasari', 4, 'Oke untuk pagi hari, tapi kurang untuk malam.'),
(19, 'Tina Wulandari', 5, 'Clay cleanser yang bersih banget! Kulit jadi matte.'),
(19, 'Ratih Kusuma', 4, 'Bagus tapi jangan pakai terlalu sering, bisa kering.'),
(20, 'Siska Handayani', 5, 'Aloe vera gel yang multifungsi. Harga super terjangkau!'),
