-- Skincare Routines
-- Jerawat
('jerawat', 1, 'Bersihkan wajah 2x sehari', 'Gunakan cleanser khusus jerawat dengan salicylic acid atau tea tree oil. Bersihkan dengan lembut, jangan digosok keras.'),
('jerawat', 2, 'Gunakan toner exfoliating', 'Pakai toner dengan AHA/BHA untuk membantu mengangkat sel kulit mati dan mencegah pori-pori tersumbat.'),
('jerawat', 3, 'Aplikasikan spot treatment', 'Oleskan gel anti-jerawat langsung pada jerawat yang meradang. Biarkan meresap sebelum lanjut ke step berikutnya.'),
('jerawat', 4, 'Pakai moisturizer ringan', 'Pilih pelembab berbasis gel atau lotion yang oil-free agar tidak menyumbat pori-pori.'),
('jerawat', 5, 'Sunscreen wajib di pagi hari', 'Gunakan sunscreen minimal SPF 30 untuk melindungi kulit dari UV yang bisa memperparah bekas jerawat.'),
-- Berminyak
('berminyak', 1, 'Cuci wajah dengan oil control cleanser', 'Bersihkan wajah 2x sehari dengan pembersih yang mengontrol minyak berlebih. Jangan terlalu sering mencuci karena bisa trigger produksi minyak lebih banyak.'),
('berminyak', 2, 'Pakai toner mattifying', 'Gunakan toner yang membantu menyeimbangkan pH kulit dan mengontrol sebum.'),
('berminyak', 3, 'Aplikasikan serum niacinamide', 'Niacinamide membantu mengecilkan pori-pori dan mengontrol produksi minyak berlebih.'),
('berminyak', 4, 'Moisturizer gel ringan', 'Kulit berminyak tetap butuh hidrasi! Pilih moisturizer berbasis gel yang cepat meresap.'),
('berminyak', 5, 'Sunscreen matte finish', 'Pilih sunscreen dengan tekstur matte atau gel untuk menghindari kilap berlebihan.'),
('berminyak', 6, 'Masker clay 1-2x seminggu', 'Gunakan clay mask untuk deep cleansing dan menyerap minyak berlebih.'),
-- Kering
('kering', 1, 'Gunakan gentle cleanser', 'Pilih pembersih yang lembut dan melembabkan. Hindari cleanser yang mengandung alkohol atau sulfate keras.'),
('kering', 2, 'Pakai hydrating toner/essence', 'Aplikasikan essence atau toner yang hydrating untuk mengembalikan kelembaban kulit.'),
('kering', 3, 'Layer serum hyaluronic acid', 'Hyaluronic acid membantu menarik dan mengunci kelembaban di kulit.'),
('kering', 4, 'Gunakan moisturizer kaya', 'Pilih moisturizer dengan tekstur krim yang mengandung ceramide untuk memperbaiki skin barrier.'),
('kering', 5, 'Aplikasikan facial oil (opsional)', 'Tambahkan facial oil di malam hari untuk extra nourishment pada kulit sangat kering.'),
('kering', 6, 'Sunscreen melembabkan', 'Gunakan sunscreen yang juga memberikan hidrasi ekstra.'),
('kering', 7, 'Pakai sleeping mask', 'Gunakan sleeping mask 2-3x seminggu untuk hidrasi intensif overnight.'),
-- Kusam
('kusam', 1, 'Exfoliate rutin', 'Gunakan gentle exfoliant 2-3x seminggu untuk mengangkat sel kulit mati yang membuat kulit kusam.'),
('kusam', 2, 'Cleanser brightening', 'Pilih pembersih dengan bahan brightening seperti vitamin C atau niacinamide.'),
('kusam', 3, 'Toner dengan AHA/BHA', 'Gunakan chemical exfoliant untuk membantu regenerasi sel kulit lebih cepat.'),
('kusam', 4, 'Serum vitamin C atau niacinamide', 'Aplikasikan serum brightening untuk mencerahkan dan meratakan warna kulit.'),
('kusam', 5, 'Moisturizer dengan brightening agent', 'Gunakan pelembab yang juga mengandung bahan pencerah.'),
('kusam', 6, 'Sunscreen setiap hari', 'SPF adalah kunci mencegah kusam karena paparan UV. Wajib pakai setiap hari!'),
('kusam', 7, 'Masker brightening 2x seminggu', 'Gunakan sheet mask atau wash-off mask untuk boost kecerahan.'),
-- Kemerahan
('kemerahan', 1, 'Gunakan gentle cleanser', 'Pilih pembersih yang sangat lembut dan tidak mengandung fragrance untuk menghindari iritasi.'),
('kemerahan', 2, 'Pakai calming toner', 'Gunakan toner dengan centella, chamomile, atau aloe vera untuk menenangkan kulit.'),
('kemerahan', 3, 'Serum anti-inflammatory', 'Aplikasikan serum dengan bahan calming seperti centella asiatica, niacinamide, atau azelaic acid.'),
('kemerahan', 4, 'Moisturizer untuk kulit sensitif', 'Pilih pelembab yang hypoallergenic dan free dari fragrance serta pewarna.'),
('kemerahan', 5, 'Sunscreen physical/mineral', 'Gunakan sunscreen berbasis zinc oxide atau titanium dioxide yang lebih gentle untuk kulit sensitif.'),
('kemerahan', 6, 'Hindari pemicu iritasi', 'Hindari produk dengan alkohol, fragrance, essential oil, dan scrub kasar.'),
('kemerahan', 7, 'Kompres dingin jika perlu', 'Gunakan kompres dingin untuk meredakan kemerahan yang sedang meradang.'),
-- Kombinasi
('kombinasi', 1, 'Bersihkan dengan balanced cleanser', 'Gunakan pembersih yang gentle tapi efektif membersihkan, tidak terlalu stripping.'),
('kombinasi', 2, 'Toner seimbang', 'Pakai toner yang hydrating tapi tidak terlalu berat, bisa dengan niacinamide.'),
('kombinasi', 3, 'Serum targeted', 'Aplikasikan serum sesuai kebutuhan area wajah (contoh: salicylic acid di T-zone, hyaluronic acid di pipi).'),
('kombinasi', 4, 'Moisturizer gel-cream', 'Pilih tekstur yang medium, bisa gel-cream hybrid yang melembabkan tanpa membuat berminyak.'),
('kombinasi', 5, 'Sunscreen hybrid', 'Gunakan sunscreen yang nyaman dan tidak membuat T-zone terlalu oily.'),
('kombinasi', 6, 'Multi-masking', 'Gunakan clay mask di T-zone dan hydrating mask di area kering saat maskeran.'),
('kombinasi', 7, 'Sesuaikan produk per area', 'Jangan takut menggunakan produk berbeda untuk zona berbeda di wajah.');
